INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''singeing'' as a pretreatment step for woven/knitted fabric?', '["Passing fabric quickly over a gas flame or heated surface to burn off protruding fiber ends/hairiness for a smoother surface","A chemical process that adds color to fabric","A process that adds extra twist to yarn within the fabric","A mechanical process that increases fabric width"]'::jsonb, 'Passing fabric quickly over a gas flame or heated surface to burn off protruding fiber ends/hairiness for a smoother surface', 'Singeing exposes fabric briefly to direct flame/heat, burning away loose protruding fiber ends without damaging the main fabric body, producing a cleaner, smoother surface — beneficial before printing or for a refined fabric hand.', 1, '{"singeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is singeing typically done before dyeing/printing rather than after?', '["Removing surface hairiness beforehand gives a cleaner surface for sharper dye/print definition and reduces the chance the singed fiber ends affect color uniformity","Singeing is only ever done as the final step after all other processing is complete","Singeing has no relationship to print/dye quality at all","Singeing removes all color from already-dyed fabric, so must be done first for that reason"]'::jsonb, 'Removing surface hairiness beforehand gives a cleaner surface for sharper dye/print definition and reduces the chance the singed fiber ends affect color uniformity', 'A smoother, less hairy fabric surface (from singeing) allows dye/print patterns to appear sharper and more even; doing it before coloring avoids any risk of singeing affecting/damaging already-applied color.', 2, '{"singeing","process-sequence"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''peroxide bleaching'' commonly used for on cotton fabric?', '["Using hydrogen peroxide under alkaline conditions to remove natural coloring matter and achieve a stable white/bleached base","Adding permanent color pigment to the fabric","Removing all size chemicals from warp yarn","Softening the fabric''s hand-feel with no whitening effect"]'::jsonb, 'Using hydrogen peroxide under alkaline conditions to remove natural coloring matter and achieve a stable white/bleached base', 'Hydrogen peroxide bleaching (typically under alkaline conditions with stabilizers) oxidizes and removes natural pigments in cotton, producing a stable, durable white base widely used because it doesn''t yellow over time like some other bleaching agents.', 1, '{"peroxide-bleaching"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is a ''stabilizer'' (like sodium silicate or organic stabilizers) added during hydrogen peroxide bleaching?', '["To control the decomposition rate of peroxide, preventing uncontrolled/excessive breakdown that could damage the fiber (over-bleaching/tendering)","To add color to the bleaching bath","To increase the fabric''s final GSM directly","To remove all peroxide before it can react with the fabric at all"]'::jsonb, 'To control the decomposition rate of peroxide, preventing uncontrolled/excessive breakdown that could damage the fiber (over-bleaching/tendering)', 'Without a stabilizer, peroxide can decompose too rapidly (especially if catalyzed by trace metal ions), releasing oxidizing radicals uncontrollably and causing fiber damage (tendering/strength loss); stabilizers moderate this decomposition for safe, controlled bleaching.', 2, '{"peroxide-stabilizer"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What does ''tendering'' refer to as a fabric damage/defect in wet processing?', '["Localized weakening/degradation of fiber strength, often from uncontrolled chemical reaction (e.g., excess bleach/acid exposure)","A finishing process that intentionally softens fabric","The process of dyeing fabric a lighter shade than intended","A mechanical process that adds extra fabric thickness"]'::jsonb, 'Localized weakening/degradation of fiber strength, often from uncontrolled chemical reaction (e.g., excess bleach/acid exposure)', 'Tendering describes fiber degradation/weakening (sometimes appearing as holes or tears later) usually caused by uncontrolled oxidative or acidic chemical damage during processing — a serious defect requiring careful process control (like proper peroxide stabilization) to avoid.', 1, '{"tendering"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of a final ''neutralization'' step often included after alkaline processes like scouring/bleaching?', '["To adjust the fabric''s pH back to a neutral/slightly acidic level appropriate for subsequent dyeing or for skin-safe finished goods","To add extra alkali to make the fabric more alkaline","To permanently dye the fabric a neutral gray color","To remove all fiber from the fabric surface"]'::jsonb, 'To adjust the fabric''s pH back to a neutral/slightly acidic level appropriate for subsequent dyeing or for skin-safe finished goods', 'After alkaline treatments (scouring, bleaching), fabric often needs neutralization (e.g., with dilute acid) to bring pH to a suitable level for the next process (many dyes need specific pH) and to ensure finished goods meet skin-safe pH standards.', 1, '{"neutralization"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is a ''jigger'' dyeing machine primarily used for?', '["Dyeing fabric in open-width (flat) form by passing it back and forth between two rollers through a dye bath","Dyeing loose fiber before spinning","Dyeing yarn wound on packages/cones","Printing patterns onto fabric"]'::jsonb, 'Dyeing fabric in open-width (flat) form by passing it back and forth between two rollers through a dye bath', 'A jigger machine holds fabric in open-width form on two rollers, repeatedly passing it through a dye bath back and forth between the rollers — commonly used for woven fabrics where rope form (twisting) might cause crease marks.', 1, '{"jigger-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is a ''jet dyeing'' machine, and what fabric form does it typically use?', '["A machine that dyes fabric in rope form, circulated by a high-velocity liquor jet through a tube, commonly used for knitted fabric","A machine used exclusively for dyeing loose fiber, never fabric","A machine that applies dye only via printing rollers, with no liquor bath","A machine used only for open-width woven fabric, never knits"]'::jsonb, 'A machine that dyes fabric in rope form, circulated by a high-velocity liquor jet through a tube, commonly used for knitted fabric', 'Jet dyeing machines circulate fabric in rope (twisted, bunched) form through a tube using a high-velocity liquor jet that both propels the fabric and delivers dye liquor — well-suited to knitted fabrics, which are more prone to distortion under open-width tension.', 1, '{"jet-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is rope-form dyeing (like jet dyeing) generally preferred for knitted fabric over open-width methods (like jigger)?', '["Knitted fabric is more elastic/distortion-prone under tension, and rope form (relaxed, minimal tension) reduces the risk of stretching or crease marks","Rope-form dyeing is always cheaper regardless of fabric type","Knitted fabric cannot physically pass through any open-width dyeing machine","Open-width dyeing always produces better results for knits than rope dyeing"]'::jsonb, 'Knitted fabric is more elastic/distortion-prone under tension, and rope form (relaxed, minimal tension) reduces the risk of stretching or crease marks', 'Knitted fabrics are inherently more stretchy and easily distorted than woven fabrics; dyeing them in relaxed rope form (rather than under the tension of open-width processing) helps preserve their dimensional stability and avoid permanent stretch marks or creases.', 2, '{"rope-dyeing","knit-fabric"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a potential drawback of rope-form dyeing (like jet dyeing) for certain woven fabrics, compared to open-width (jigger) dyeing?', '["The rope''s folding/bunching action can cause permanent crease marks on fabrics prone to creasing, unlike the flat, tension-controlled open-width method","Rope-form dyeing is always faster and defect-free for every fabric type with no exceptions","Rope dyeing uses no water or chemicals at all, unlike jigger dyeing","Open-width dyeing cannot be used for any woven fabric"]'::jsonb, 'The rope''s folding/bunching action can cause permanent crease marks on fabrics prone to creasing, unlike the flat, tension-controlled open-width method', 'Since rope dyeing repeatedly folds/bunches the fabric as it circulates, certain fabrics (especially some woven structures prone to crease-retention) can develop permanent crease marks — open-width methods like jigger avoid this by keeping fabric flat under controlled tension throughout.', 2, '{"rope-dyeing-drawback"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of a ''stenter'' (tenter frame) in fabric finishing?', '["To hold fabric at a controlled width (using clips or pins) while it passes through a heat chamber for drying, heat-setting, or width control","To apply dye to loose fiber before spinning","To insert weft yarn during weaving","To measure the exact color shade of dyed fabric"]'::jsonb, 'To hold fabric at a controlled width (using clips or pins) while it passes through a heat chamber for drying, heat-setting, or width control', 'A stenter grips fabric edges with clips or pins and stretches it to a precise controlled width while conveying it through a heated chamber — used for drying, heat-setting synthetic fibers, and correcting/stabilizing fabric width and grain (skew/bow).', 1, '{"stenter"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is heat-setting on a stenter especially important for fabrics containing thermoplastic synthetic fiber (like polyester)?', '["Heat above the fiber''s glass transition temperature allows the polymer structure to relax into a new stable state, locking in the fabric''s dimensions and reducing later shrinkage/distortion","Heat-setting has no effect whatsoever on any synthetic fiber''s dimensional stability","Heat-setting is only relevant for 100% cotton fabric, not synthetics","Heat-setting permanently removes all color from the fabric"]'::jsonb, 'Heat above the fiber''s glass transition temperature allows the polymer structure to relax into a new stable state, locking in the fabric''s dimensions and reducing later shrinkage/distortion', 'Thermoplastic fibers like polyester can be heat-set: heating above the glass transition (but below melting) temperature while held at a specific width allows internal polymer chains to relax and ''freeze'' into that new configuration upon cooling, locking in dimensional stability and reducing future shrinkage during use/washing.', 2, '{"heat-setting","polyester"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What does ''fabric bow'' and ''fabric skew'' refer to as finishing-related fabric defects?', '["Distortion where weft yarns (bow) curve across the fabric width, or the whole grain shifts diagonally (skew), instead of running perfectly perpendicular/straight to the warp","A defect where the fabric changes color unexpectedly","A defect only related to yarn twist direction, unrelated to fabric grain","A defect that only affects the fabric''s final weight (GSM), not its shape"]'::jsonb, 'Distortion where weft yarns (bow) curve across the fabric width, or the whole grain shifts diagonally (skew), instead of running perfectly perpendicular/straight to the warp', 'Bow describes weft yarns curving into a bow shape across the fabric width; skew describes the weft grain shifting at an angle relative to the warp — both are grain distortions that a properly adjusted stenter (and correct handling through prior wet processes) helps correct before final finishing.', 2, '{"fabric-bow-skew"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why do bow and skew defects matter for garments cut and sewn from the fabric (e.g., striped or checked patterns)?', '["Distorted grain can cause visible pattern misalignment (e.g., crooked stripes) and uneven garment twisting/hang after washing","Bow and skew have no visible or functional effect on any finished garment","These defects only matter for solid-color fabric with no pattern at all","Bow and skew only affect fabric color, not its physical shape"]'::jsonb, 'Distorted grain can cause visible pattern misalignment (e.g., crooked stripes) and uneven garment twisting/hang after washing', 'If fabric grain is distorted (bow/skew) when garments are cut, patterns like stripes/checks may not align correctly, and garments can develop a visibly twisted appearance (seams torquing) especially after washing as the fabric relaxes further — a significant quality complaint in apparel.', 2, '{"bow-skew-garment-impact"}'::text[]);
